15	 {"id": "CLM-038", "quote": "Markers: **●** confirmed · **◐** policy/standards only · **○** grey/thin. Unmarked is an error.", "modality": "DEFINES", "subject": "markers", "claim": "Markers ● confirmed, ◐ policy/standards only, ○ grey/thin; unmarked is an error.", "scope": {"stages": ["specification", "render"], "objects": []}, "speaker": "PROCESS_RULE", "date": null, "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null, "source": "CLAUDE.md:362", "quote_occurrences": 1}
16	 {"id": "CLM-039", "quote": "Work from the **ICF/access-need frame with codes AND names**, never bare axis codes, never population", "modality": "MUST", "subject": "ICF/need frame with names", "claim": "Frame work from ICF and access-need codes with names, never bare axis codes or population umbrellas.", "scope": {"stages": ["research", "judgment"], "objects": []}, "speaker": "PROCESS_RULE", "date": null, "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null, "source": "CLAUDE.md:368", "quote_occurrences": 1}
17	 {"id": "CLM-040", "quote": "harvest concepts at evidence (`db.py observe-term`, verbatim and unjudged), adjudicate at", "modality": "MUST", "subject": "harvest/adjudicate", "claim": "Harvest concepts at evidence via observe-term (verbatim, unjudged); adjudicate at judgment; the crossing is judgment's output.", "scope": {"stages": ["evidence", "judgment"], "objects": []}, "speaker": "OWNER_QUOTED", "date": "2026-08-27", "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null, "source": "CLAUDE.md:370", "quote_occurrences": 1}
18	-{"id": "CLM-041", "quote": "Only Opus-class models write `best_practice_synthesis`.", "modality": "MUST", "subject": "synthesis authorship", "claim": "Only Opus-class (or above, including Fable-class) models write best_practice_synthesis.", "scope": {"stages": ["synthesis"], "objects": []}, "speaker": "PROCESS_RULE", "date": null, "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null, "source": "CLAUDE.md:371", "quote_occurrences": 1}
19	+{"id": "CLM-041", "quote": "Only Opus-class models write `best_practice_synthesis`.", "modality": "MUST", "subject": "synthesis authorship", "claim": "Only Opus-class models write best_practice_synthesis.", "scope": {"stages": ["synthesis"], "objects": []}, "speaker": "PROCESS_RULE", "date": null, "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": "LED-061 and PIP-22 widen the floor to opus-class or fable-class; CLAUDE.md section 6 states only Opus-class.", "source": "CLAUDE.md:371", "quote_occurrences": 1}
20	 {"id": "CLM-042", "quote": "takes **four lens columns, one CHECK, real FKs, and `population_code` is retired in favour of the four**", "modality": "MUST", "subject": "lens columns", "claim": "Any table attaching a determination to a group of disabled people takes four lens columns, one CHECK (at least one), real FKs; population_code is retired.", "scope": {"stages": ["specification", "judgment", "evidence"], "objects": []}, "speaker": "OWNER_QUOTED", "date": "2026-08-28", "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null, "source": "CLAUDE.md:377", "quote_occurrences": 1}
21	 {"id": "CLM-043", "quote": "Do not read `slug × population` as any part of the answer", "modality": "MUST_NOT", "subject": "slug x population key", "claim": "slug x population must not be read as any part of the determination key.", "scope": {"stages": ["specification"], "objects": []}, "speaker": "PROCESS_RULE", "date": null, "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null, "source": "CLAUDE.md:391", "quote_occurrences": 1}
22	 {"id": "CLM-044", "quote": "A publisher block (403, a Cloudflare/Bunny-Shield JS challenge, a paywall on a page that used to be free) is not terminal — try the Internet Archive before giving up (R10).", "modality": "MUST", "subject": "publisher block", "claim": "A publisher block is not terminal: try the Internet Archive and persist through retrieval_log.fetch.", "scope": {"stages": ["evidence"], "objects": []}, "speaker": "PROCESS_RULE", "date": null, "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null, "source": "CLAUDE.md:398", "quote_occurrences": 1}
