28	 {"id": "DRS-078", "source": "decisions/DR-2026-08-27-concept-vocabulary-harvested-at-evidence-adjudicated-at-judgment.md:1", "quote": "The concept vocabulary is harvested at evidence and adjudicated at judgment.", "modality": "MUST", "subject": "concept vocabulary harvest", "claim": "The concept vocabulary is harvested at the evidence stage, as terms observed in sources, without adjudication.", "scope": {"stages": ["evidence"], "objects": ["observe-term", "terms", "term_aliases"]}, "speaker": "RATIFIED_DOC", "date": "2026-08-27", "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": "The same title also states the adjudication half (adjudicated at judgment), recorded as a separate atom."}
29	 {"id": "DRS-079", "source": "decisions/DR-2026-08-27-concept-vocabulary-harvested-at-evidence-adjudicated-at-judgment.md:27", "quote": "Judgment then adjudicates with the source in hand, and the vocabulary is grown with warrant.", "modality": "MUST", "subject": "adjudication of concepts", "claim": "Judgment adjudicates harvested concepts with the source in hand and grows the vocabulary with warrant.", "scope": {"stages": ["judgment"], "objects": ["terms", "term_aliases"]}, "speaker": "RATIFIED_DOC", "date": "2026-08-27", "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null}
30	 {"id": "DRS-080", "source": "decisions/DR-2026-08-27-concept-vocabulary-harvested-at-evidence-adjudicated-at-judgment.md:25", "quote": "Recording that a source uses a phrase is a fact about the document, not a claim that the phrase names one of our categories", "modality": "DEFINES", "subject": "nature of a harvested term", "claim": "Recording that a source uses a phrase is a fact about the document and not a claim that the phrase names one of the project's categories.", "scope": {"stages": ["evidence"], "objects": ["observe-term"]}, "speaker": "RATIFIED_DOC", "date": "2026-08-27", "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null}
31	-{"id": "DRS-081", "source": "decisions/DR-2026-08-27-concept-vocabulary-harvested-at-evidence-adjudicated-at-judgment.md:21", "quote": "we do not want to presuppose categories/concepts/approaches/elements/techniques/practices by defining them all at the start of the project.", "modality": "MUST_NOT", "subject": "up-front definition of concepts", "claim": "Categories, concepts, approaches, elements, techniques and practices must not be presupposed by defining them all at the start of the project.", "scope": {"stages": ["base", "research"], "objects": ["terms"]}, "speaker": "OWNER_QUOTED", "date": "2026-08-27", "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null}
32	+{"id": "DRS-081", "source": "decisions/DR-2026-08-27-concept-vocabulary-harvested-at-evidence-adjudicated-at-judgment.md:21", "quote": "we do not want to presuppose categories/concepts/approaches/elements/techniques/practices by defining them all at the start of the project. however, we also can't perform our research properly if we don't presuppose all of those.", "modality": "DEFINES", "subject": "the vocabulary aporia the DR resolves", "claim": "The owner states a tension: the project does not want to presuppose its categories by defining them all at the start, yet research cannot proceed properly without presupposing them; the DR calls this a false dilemma and resolves it by observing phrases without adjudicating them.", "scope": {"stages": ["base", "research"], "objects": ["terms"]}, "speaker": "OWNER_QUOTED", "date": "2026-08-27", "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": "One horn of this tension, quoted alone, reads as a prohibition; the next sentence of the DR rejects the dilemma. The binding ruling is the adoption quoted in the DR header (LED-113 / D-0173)."}
33	 {"id": "DRS-082", "source": "decisions/DR-2026-08-27-concept-vocabulary-harvested-at-evidence-adjudicated-at-judgment.md:39", "quote": "Stipulate the vocabulary up front -- rejected by the owner as the presupposition the aporia warns against.", "modality": "MUST_NOT", "subject": "stipulating the vocabulary up front", "claim": "The vocabulary must not be stipulated up front.", "scope": {"stages": ["base", "research"], "objects": ["terms"]}, "speaker": "RATIFIED_DOC", "date": "2026-08-27", "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": null, "ambiguity": null}
