50	 {"id": "EVI-226", "source": "governance/evidence-architecture.md:183", "quote": "Any rendering that shows a regulatory floor value alongside an evidence-anchored value must show both and label which is which", "modality": "MUST", "subject": "Invariant I2: floor-anchor pairing", "claim": "A rendering showing a regulatory floor value alongside an evidence-anchored value must show both and label which is which.", "scope": {"stages": ["render"], "objects": ["register map"]}, "speaker": "RATIFIED_DOC", "date": null, "status": "ACTIVE", "status_evidence": null, "superseded_by": null, "enforcement": "scripts/audit/register_integrity_check.py", "ambiguity": null}
