def verify_atoms(atoms, repo=REPO):
    """Every quote must occur verbatim (whitespace collapsed, leading '> ' ignored) in its source file."""
    bad, cache = [], {}
    def doc(path):
        if path not in cache:
            raw = read(repo, path)
            cache[path] = norm("\n".join(re.sub(r"^\s*>\s?", "", l) for l in raw.split("\n")))
